# break — exit loop immediately
print("Finding first enemy...")
enemies = ["goblin", "orc", "dragon", "goblin", "troll"]

for enemy in enemies:
    if enemy == "dragon":
        print(f"Found a {enemy}! Retreat!")
        break  # Exit loop when dragon found
    print(f"{enemy} is too weak")

print("Escaping!\n")

# continue — skip this iteration and continue
print("Counting enemies (skip goblins):")
for enemy in enemies:
    if enemy == "goblin":
        continue  # Skip goblins
    print(f"{enemy} is a threat!")

print("\n")

# pass — do nothing (placeholder)
print("Planning attacks:")
for enemy in enemies:
    if enemy == "dragon":
        pass  # TODO: Dragon strategy later
    else:
        print(f"Attack {enemy}!")
